std::string write_test_file( const std::string & name, const std::string & content )
{
    const std::string path = ".test_" + name + ".csv";
    std::ofstream out( path, std::ios::binary | std::ios::trunc );
    out.write( content.data(), (std::streamsize)content.size() );
    out.close();
    return path;
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
std::string join_fields( const std::vector<std::string> & fields )
{
    std::string s;
    for( std::size_t i = 0; i < fields.size(); ++i ) {
        if( i ) {
            s += ';';
        }
        s += fields[i];
    }
    return s;
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
std::vector<std::string> read_forward( CSVUtil & csv )
{
    std::vector<std::string> lines;
    for( auto it = csv.begin(); it != csv.end(); it++ ) {
        lines.push_back( join_fields( *it ) );
    }
    return lines;
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
std::vector<std::string> read_backward( CSVUtil & csv )
{
    std::vector<std::string> lines;
    for( auto it = csv.rbegin(); it != csv.rend(); it++ ) {
        lines.push_back( join_fields( *it ) );
    }
    return lines;
}
