std::shared_ptr<TestCaseBase<bool>> test_case_many_lines()
{
    return std::make_shared<TestCaseFuncNoInp>( __FUNCTION__, true, []() {
        std::string content;
        const int count = 20000;
        for( int i = 0; i < count; ++i ) {
            content += std::to_string( i );
            content += ";v\n";
        }

        const std::string f = write_test_file( "many_lines", content );

        Lines fwd;
        Lines bwd;
        {
            CSVUtil csv( f );
            fwd = read_forward( csv );
            bwd = read_backward( csv );
        }
        std::filesystem::remove( f );

        if( (int)fwd.size() != count || (int)bwd.size() != count ) {
            return false;
        }
        if( fwd.front() != "0;v" || fwd.back() != "19999;v" ) {
            return false;
        }
        if( bwd.front() != "19999;v" || bwd.back() != "0;v" ) {
            return false;
        }
        return true;
    });
}
